from __future__ import annotations

"""Strict, top-level-only Playground command parsing and routing."""

import copy
import json
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import IntInput, MessageTextInput, Output
from lfx.schema import Data


SCHEMA_VERSION = "playground-command/v1"
ALLOWED_COMMANDS = {"start", "submit_answers", "approve", "reject", "cancel"}
START_KEYS = {"schema_version", "command", "request_text", "additional_prompt"}
ANSWER_KEYS = {
    "schema_version", "command", "channel_mode", "work_definition_id", "batch_id", "session_id",
    "expected_revision", "idempotency_key", "answers", "submitted_at",
}
ACTION_KEYS = {"schema_version", "command"}


def _failure(code: str, message: str, trace_id: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "route": "blocked_path",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


def _reject_constant(_: str) -> None:
    raise ValueError("non-finite JSON number")


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def _input_text(value: Any) -> str:
    text = getattr(value, "text", value if isinstance(value, str) else "")
    return text if isinstance(text, str) else ""


def parse_playground_command(value: Any, *, max_input_chars: Any = 200_000) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        maximum = max(1_000, min(int(max_input_chars), 500_000))
    except (TypeError, ValueError):
        maximum = 200_000
    raw = _input_text(value)
    if not raw.strip() or len(raw) > maximum:
        return _failure("PLAYGROUND_COMMAND_SIZE_INVALID", "명령 JSON이 비어 있거나 허용 크기를 초과했습니다.", trace_id)
    try:
        payload = json.loads(raw, object_pairs_hook=_unique_object, parse_constant=_reject_constant)
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("PLAYGROUND_COMMAND_JSON_INVALID", "중복 key가 없는 단일 JSON object가 필요합니다.", trace_id)
    if not isinstance(payload, dict):
        return _failure("PLAYGROUND_COMMAND_OBJECT_REQUIRED", "Playground 명령은 JSON object여야 합니다.", trace_id)
    if payload.get("schema_version") not in (None, SCHEMA_VERSION):
        return _failure("PLAYGROUND_COMMAND_SCHEMA_INVALID", "지원하지 않는 Playground 명령 schema입니다.", trace_id)
    command = payload.get("command")
    if type(command) is not str or command not in ALLOWED_COMMANDS:
        return _failure("PLAYGROUND_COMMAND_INVALID", "지원하는 최상위 command가 필요합니다.", trace_id)

    allowed_keys = START_KEYS if command == "start" else ANSWER_KEYS if command == "submit_answers" else ACTION_KEYS
    if set(payload) - allowed_keys:
        return _failure("PLAYGROUND_COMMAND_FIELDS_INVALID", "command에 허용되지 않은 최상위 필드가 있습니다.", trace_id)
    if command == "start":
        request_text = payload.get("request_text")
        additional_prompt = payload.get("additional_prompt", "")
        if type(request_text) is not str or not request_text.strip() or len(request_text) > 50_000:
            return _failure("PLAYGROUND_START_REQUEST_INVALID", "start에는 1~50000자의 request_text가 필요합니다.", trace_id)
        if type(additional_prompt) is not str or len(additional_prompt) > 20_000:
            return _failure("PLAYGROUND_START_PROMPT_INVALID", "additional_prompt는 20000자 이하 문자열이어야 합니다.", trace_id)
    elif command == "submit_answers":
        required = {
            "channel_mode", "work_definition_id", "batch_id", "session_id", "expected_revision",
            "idempotency_key", "answers",
        }
        if required - set(payload) or payload.get("channel_mode") != "playground":
            return _failure("PLAYGROUND_ANSWER_FIELDS_REQUIRED", "submit_answers 필수 identity와 playground channel이 필요합니다.", trace_id)
        for field in ("work_definition_id", "batch_id", "session_id", "idempotency_key"):
            if type(payload.get(field)) is not str or not payload[field] or len(payload[field]) > 300:
                return _failure("PLAYGROUND_ANSWER_IDENTITY_INVALID", "submit_answers identity가 유효하지 않습니다.", trace_id)
        revision = payload.get("expected_revision")
        if type(revision) is not int or revision < 0:
            return _failure("PLAYGROUND_ANSWER_REVISION_INVALID", "expected_revision은 0 이상의 정수여야 합니다.", trace_id)
        answers = payload.get("answers")
        if not isinstance(answers, (dict, list)):
            return _failure("PLAYGROUND_ANSWER_LIST_INVALID", "answers는 object 또는 array여야 합니다.", trace_id)
        if "submitted_at" in payload and type(payload["submitted_at"]) is not str:
            return _failure("PLAYGROUND_ANSWER_TIMESTAMP_INVALID", "submitted_at은 문자열이어야 합니다.", trace_id)

    routed = copy.deepcopy(payload)
    routed.update(
        {
            "schema_version": SCHEMA_VERSION,
            "ok": True,
            "status": "ROUTED",
            "route": f"{command}_path",
            "trace_id": trace_id,
        }
    )
    return routed


class PlaygroundCommandRouterComponent(Component):
    display_name = "36 Playground Command Router"
    description = "중복 key와 nested command 우회를 거부하고 검증된 최상위 command 경로 하나만 엽니다."
    icon = "GitBranch"
    name = "PlaygroundCommandRouter"

    inputs = [
        MessageTextInput(name="input_text", display_name="Structured Command JSON", required=True),
        IntInput(name="max_input_chars", display_name="Maximum Input Characters", value=200_000, advanced=True),
    ]
    outputs = [
        Output(name="start_path", display_name="Start", method="route_command", types=["Data"], group_outputs=True),
        Output(name="submit_answers_path", display_name="Submit Answers", method="route_command", types=["Data"], group_outputs=True),
        Output(name="approve_path", display_name="Approve", method="route_command", types=["Data"], group_outputs=True),
        Output(name="reject_path", display_name="Reject", method="route_command", types=["Data"], group_outputs=True),
        Output(name="cancel_path", display_name="Cancel", method="route_command", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="Blocked", method="route_command", types=["Data"], group_outputs=True),
    ]

    def route_command(self) -> Data:
        result = getattr(self, "_parsed_command", None)
        if not isinstance(result, dict):
            result = parse_playground_command(
                getattr(self, "input_text", ""),
                max_input_chars=getattr(self, "max_input_chars", 200_000),
            )
            self._parsed_command = result
        selected = str(result.get("route") or "blocked_path")
        for output_name in (
            "start_path", "submit_answers_path", "approve_path", "reject_path", "cancel_path", "blocked_path",
        ):
            if output_name != selected:
                self.stop(output_name)
        self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": selected}
        return Data(data=copy.deepcopy(result))

from __future__ import annotations

import copy
import hashlib
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


SCHEMA_VERSION = "work-definition/v1"
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}
SCALAR_FACT_FIELDS = ("goal", "trigger", "frequency_volume", "sla", "automation_intent")
LIST_FIELDS = (
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "decisions",
    "exceptions",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "assumptions",
    "unresolved",
)


def _payload(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (dict, list)):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list)):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        candidate = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)
        return json.loads(candidate)
    return None


def _unwrap_named(payload: Any, *names: str) -> dict[str, Any]:
    if not isinstance(payload, dict):
        return {}
    for name in names:
        nested = payload.get(name)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return copy.deepcopy(payload)


def _safe_id(value: Any, prefix: str, material: str) -> str:
    supplied = re.sub(r"[^A-Za-z0-9_.:-]+", "-", str(value or "").strip())[:200].strip("-")
    if supplied:
        return supplied
    return f"{prefix}-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:20]}"


def _evidence_ids(value: Any, fallback_turn: str) -> list[str]:
    raw = value if isinstance(value, list) else []
    result: list[str] = []
    for item in raw + ([fallback_turn] if fallback_turn else []):
        text = str(item or "").strip()[:200]
        if text and text not in result:
            result.append(text)
    return result[:50]


def _fact(value: Any, *, revision: int, turn_id: str, existing: Any = None) -> dict[str, Any]:
    if isinstance(existing, dict) and existing.get("status") in FACT_STATUSES and "value" in existing:
        prior = copy.deepcopy(existing)
    else:
        prior = None
    source = value if isinstance(value, dict) and "value" in value else {"value": value}
    supplied_value = source.get("value")
    if supplied_value in (None, "", [], {}):
        if prior is not None:
            return prior
        return {
            "value": None,
            "status": "unknown",
            "evidence_turn_ids": [],
            "confidence": 0.0,
            "last_updated_revision": revision,
        }
    if prior is not None and prior.get("status") in {"confirmed", "conflicting"}:
        # A model-normalization stage cannot replace user-confirmed evidence.
        return prior
    requested_status = str(source.get("status") or "inferred").lower()
    status = requested_status if requested_status in {"inferred", "unknown", "conflicting"} else "inferred"
    try:
        confidence = float(source.get("confidence", 0.7 if status == "inferred" else 0.0))
    except (TypeError, ValueError):
        confidence = 0.0
    return {
        "value": copy.deepcopy(supplied_value),
        "status": status,
        "evidence_turn_ids": _evidence_ids(source.get("evidence_turn_ids"), turn_id),
        "confidence": max(0.0, min(confidence, 1.0)),
        "last_updated_revision": revision,
    }


def _list_item(item: Any, *, field: str, index: int, work_id: str, revision: int, turn_id: str) -> dict[str, Any]:
    record = copy.deepcopy(item) if isinstance(item, dict) else {"value": copy.deepcopy(item)}
    identity = record.get("id") or record.get(f"{field[:-1]}_id") or record.get("step_id") or record.get("name") or record.get("label") or record.get("title") or record.get("value")
    item_id = _safe_id(identity, field.rstrip("s") or "item", f"{work_id}|{field}|{index}|{json.dumps(record, sort_keys=True, ensure_ascii=False, default=str)}")
    record.setdefault("id", item_id)
    supplied_provenance = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
    requested_status = str(supplied_provenance.get("status") or record.pop("status", "inferred")).lower()
    try:
        confidence = float(supplied_provenance.get("confidence", 0.7))
    except (TypeError, ValueError):
        confidence = 0.0
    record["provenance"] = {
        "status": requested_status if requested_status in {"inferred", "unknown", "conflicting"} else "inferred",
        "evidence_turn_ids": _evidence_ids(supplied_provenance.get("evidence_turn_ids") or record.pop("evidence_turn_ids", []), turn_id),
        "confidence": max(0.0, min(confidence, 1.0)),
        "last_updated_revision": revision,
    }
    return record


def _merge_lists(candidate: Any, existing: Any, *, field: str, work_id: str, revision: int, turn_id: str) -> list[dict[str, Any]]:
    prior = copy.deepcopy(existing) if isinstance(existing, list) else []
    incoming = candidate if isinstance(candidate, list) else ([] if candidate in (None, "") else [candidate])
    by_id: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for index, item in enumerate(prior):
        if not isinstance(item, dict):
            item = {"value": item}
        normalized = copy.deepcopy(item)
        item_id = _safe_id(normalized.get("id"), field.rstrip("s") or "item", f"{work_id}|{field}|prior|{index}")
        normalized["id"] = item_id
        by_id[item_id] = normalized
        order.append(item_id)
    for index, item in enumerate(incoming):
        normalized = _list_item(item, field=field, index=index, work_id=work_id, revision=revision, turn_id=turn_id)
        item_id = normalized["id"]
        prior_item = by_id.get(item_id)
        prior_status = ((prior_item or {}).get("provenance") or {}).get("status") if isinstance(prior_item, dict) else None
        if prior_item is not None and prior_status in {"confirmed", "conflicting"}:
            continue
        by_id[item_id] = normalized
        if item_id not in order:
            order.append(item_id)
    return [by_id[item_id] for item_id in order]


def normalize_work_definition(candidate_value: Any, envelope_value: Any, existing_value: Any = None) -> dict[str, Any]:
    try:
        candidate = _unwrap_named(_payload(candidate_value), "work_definition", "candidate")
        envelope = _unwrap_named(_payload(envelope_value), "envelope")
        existing = _unwrap_named(_payload(existing_value), "work_definition") if existing_value is not None else {}
    except (TypeError, ValueError, json.JSONDecodeError):
        candidate, envelope, existing = {}, {}, {}
    trace_id = f"trace-{uuid.uuid4()}"
    required_envelope = ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "source_request")
    missing = [key for key in required_envelope if not envelope.get(key)]
    if missing or not isinstance(candidate, dict):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "WORK_DEFINITION_INPUT_INVALID",
                "message": "업무 정의 후보 또는 요청 Envelope가 유효하지 않습니다.",
                "retryable": False,
                "details": {"missing_envelope_fields": missing},
            },
            "resume": None,
            "trace_id": trace_id,
        }

    work_id = str(envelope["work_definition_id"])
    if existing and any(str(existing.get(key, "")) != str(envelope.get(key, "")) for key in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode")):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_IDENTITY_MISMATCH", "message": "기존 업무 정의와 요청의 tenant/session 식별자가 다릅니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        revision = int(existing.get("revision", envelope.get("expected_revision", 0)) or 0)
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "WorkDefinition revision은 0 이상의 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    if revision < 0:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "WorkDefinition revision은 0 이상의 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    source = envelope.get("source_request") if isinstance(envelope.get("source_request"), dict) else {}
    turn_id = str(source.get("turn_id") or "")
    document: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "work_definition_id": work_id,
        "tenant_id": str(envelope["tenant_id"]),
        "owner_id": str(envelope["owner_id"]),
        "session_id": str(envelope["session_id"]),
        "channel_mode": str(envelope["channel_mode"]),
        "revision": revision,
        "status": "EXTRACTING",
        "source_requests": copy.deepcopy(existing.get("source_requests", [])) if isinstance(existing.get("source_requests"), list) else [],
        "preview_hash": existing.get("preview_hash"),
        "approved_hash": existing.get("approved_hash"),
        "as_is_graph": copy.deepcopy(existing.get("as_is_graph") or candidate.get("as_is_graph") or {"nodes": [], "edges": []}),
        "processed_answer_batches": copy.deepcopy(existing.get("processed_answer_batches", [])),
    }
    if source and not any(item.get("turn_id") == turn_id for item in document["source_requests"] if isinstance(item, dict)):
        document["source_requests"].append(copy.deepcopy(source))

    for field in SCALAR_FACT_FIELDS:
        document[field] = _fact(candidate.get(field), revision=revision, turn_id=turn_id, existing=existing.get(field))
    for field in LIST_FIELDS:
        document[field] = _merge_lists(candidate.get(field), existing.get(field), field=field, work_id=work_id, revision=revision, turn_id=turn_id)

    # Keep only explicitly namespaced extensions; arbitrary model output does
    # not become an executable or trusted WorkDefinition field.
    extensions = candidate.get("extensions")
    if isinstance(extensions, dict):
        document["extensions"] = copy.deepcopy(extensions)

    return {
        "ok": True,
        "status": document["status"],
        "artifact_refs": [{"kind": "work_definition", "id": work_id, "revision": revision}],
        "work_definition": document,
        "trace_id": trace_id,
    }


class WorkDefinitionNormalizerComponent(Component):
    display_name = "11 업무 정의 정규화"
    description = "모델의 JSON 후보를 stable ID와 provenance가 있는 WorkDefinition v1으로 결정론적으로 정규화합니다."
    icon = "Braces"
    name = "WorkDefinitionNormalizer"

    inputs = [
        DataInput(name="candidate", display_name="모델 추출 후보", input_types=["Data", "Message", "JSON"], required=True),
        DataInput(name="request_envelope", display_name="업무 요청 Envelope", input_types=["Data", "JSON"], required=True),
        DataInput(name="existing_work_definition", display_name="기존 WorkDefinition", input_types=["Data", "JSON"], required=False, advanced=True),
    ]
    outputs = [Output(name="work_definition", display_name="정규화 WorkDefinition", method="build_work_definition", types=["Data"])]

    def build_work_definition(self) -> Data:
        result = normalize_work_definition(
            getattr(self, "candidate", None),
            getattr(self, "request_envelope", None),
            getattr(self, "existing_work_definition", None),
        )
        self.status = {"ok": result["ok"], "status": result["status"]}
        return Data(data=result)

from __future__ import annotations

"""Fail-closed routing for standalone Langflow component result envelopes."""

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema import Data


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if not isinstance(text, str) or not text.strip():
        return {}
    parsed = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return copy.deepcopy(parsed) if isinstance(parsed, dict) else {}


def _field(payload: dict[str, Any], path: str) -> Any:
    current: Any = payload
    for token in [item.strip() for item in path.split(".") if item.strip()]:
        if not isinstance(current, dict) or token not in current:
            return None
        current = current[token]
    return current


def gate_result(value: Any, *, required_field: Any = "") -> dict[str, Any]:
    """Return a canonical success/failure envelope without trusting truthy values."""

    trace_id = f"trace-{uuid.uuid4()}"
    try:
        payload = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        payload = {}
    required = str(required_field or "").strip()
    if payload.get("ok") is True and (not required or _field(payload, required) not in (None, "")):
        return payload
    if payload.get("ok") is False and isinstance(payload.get("error"), dict):
        return payload
    code = "RESULT_REQUIRED_FIELD_MISSING" if payload.get("ok") is True and required else "RESULT_ENVELOPE_INVALID"
    message = (
        f"성공 결과에 필수 필드 '{required}'가 없습니다."
        if code == "RESULT_REQUIRED_FIELD_MISSING"
        else "이전 단계가 명시적인 ok=true 결과를 반환하지 않았습니다."
    )
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {
            "code": code,
            "message": message,
            "retryable": False,
            "details": {"required_field": required} if required else {},
        },
        "resume": None,
        "trace_id": str(payload.get("trace_id") or trace_id)[:200],
    }


class ResultGateComponent(Component):
    display_name = "35 Result Gate"
    description = "ok=true와 필수 payload 필드를 확인하고 성공·차단 경로를 물리적으로 분리합니다."
    icon = "ShieldCheck"
    name = "ResultGate"

    inputs = [
        DataInput(name="result", display_name="Result Envelope", input_types=["Data", "JSON"], required=True),
        MessageTextInput(
            name="required_field",
            display_name="Required Success Field",
            value="",
            required=False,
            advanced=True,
            info="성공 경로에서 반드시 존재해야 하는 점 표기 payload 필드입니다.",
        ),
    ]
    outputs = [
        Output(name="success_path", display_name="Verified Success", method="route_result", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="Blocked Result", method="route_result", types=["Data"], group_outputs=True),
    ]

    def route_result(self) -> Data:
        result = getattr(self, "_gated_result", None)
        if not isinstance(result, dict):
            result = gate_result(
                getattr(self, "result", None),
                required_field=getattr(self, "required_field", ""),
            )
            self._gated_result = result
        selected = "success_path" if result.get("ok") is True else "blocked_path"
        for output_name in ("success_path", "blocked_path"):
            if output_name != selected:
                self.stop(output_name)
        self.status = {
            "ok": result.get("ok"),
            "status": result.get("status"),
            "route": selected,
            "required_field": str(getattr(self, "required_field", "") or ""),
        }
        return Data(data=copy.deepcopy(result))

from __future__ import annotations

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        payload = copy.deepcopy(value)
    else:
        data = getattr(value, "data", None)
        if isinstance(data, dict):
            payload = copy.deepcopy(data)
        else:
            text = getattr(value, "text", value if isinstance(value, str) else "")
            payload = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)) if isinstance(text, str) and text.strip() else {}
    nested = payload.get("work_definition")
    return copy.deepcopy(nested) if isinstance(nested, dict) else payload


def _fact_status(value: Any) -> str:
    if isinstance(value, dict) and value.get("status") in FACT_STATUSES and "value" in value:
        return str(value["status"])
    if value in (None, "", [], {}):
        return "unknown"
    if isinstance(value, list):
        item_statuses = []
        for item in value:
            provenance = item.get("provenance", {}) if isinstance(item, dict) else {}
            status = provenance.get("status") if isinstance(provenance, dict) else None
            if status in FACT_STATUSES:
                item_statuses.append(status)
        if "conflicting" in item_statuses:
            return "conflicting"
        if item_statuses and all(status == "confirmed" for status in item_statuses):
            return "confirmed"
        return "inferred"
    return "inferred"


def _plain_text(value: Any) -> str:
    if isinstance(value, dict) and "value" in value:
        value = value.get("value")
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, default=str).lower()
    return str(value or "").lower()


def _gap(code: str, path: str, priority: str, message: str, status: str = "unknown") -> dict[str, Any]:
    return {
        "reason_code": code,
        "target_paths": [path],
        "priority": priority,
        "current_status": status,
        "message": message,
    }


def evaluate_work_completeness(value: Any) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        work = {}
    required_identity = ("work_definition_id", "tenant_id", "session_id", "revision")
    missing_identity = [key for key in required_identity if key not in work or work.get(key) in (None, "")]
    if missing_identity:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_SCHEMA_INVALID", "message": "완전성 평가에 필요한 WorkDefinition 식별자가 없습니다.", "retryable": False, "details": {"fields": missing_identity}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        revision = int(work["revision"])
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "완전성 평가 revision은 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    gaps: list[dict[str, Any]] = []
    for field, code, message in (
        ("goal", "GOAL_UNKNOWN", "업무 목적과 완료 결과가 확인되지 않았습니다."),
        ("trigger", "TRIGGER_UNKNOWN", "업무 시작 조건 또는 주기가 확인되지 않았습니다."),
        ("inputs", "INPUT_CONTRACT_UNKNOWN", "핵심 입력과 형식이 확인되지 않았습니다."),
        ("outputs", "OUTPUT_CONTRACT_UNKNOWN", "핵심 출력과 전달 대상이 확인되지 않았습니다."),
        ("actors", "PRIMARY_ACTOR_UNKNOWN", "주요 수행자 또는 책임자가 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "contract", message, status))

    steps = work.get("steps") if isinstance(work.get("steps"), list) else []
    decisions = work.get("decisions") if isinstance(work.get("decisions"), list) else []
    all_text = " ".join(_plain_text(work.get(field)) for field in ("steps", "systems", "outputs", "risks_controls", "automation_intent"))
    write_or_send = bool(re.search(r"(저장|수정|삭제|발송|전송|등록|승인|write|update|delete|send|post)", all_text))
    sensitive = bool(re.search(r"(개인정보|민감|기밀|비밀번호|인증|토큰|secret|personal|restricted)", all_text))
    review_present = "human_review" in _plain_text(work.get("as_is_graph")) or bool(re.search(r"(사람|담당자|검토|승인|human.review)", _plain_text(work.get("risks_controls"))))
    if (write_or_send or sensitive) and not review_present:
        gaps.append(_gap("WRITE_APPROVAL_UNKNOWN" if write_or_send else "SENSITIVE_REVIEW_UNKNOWN", "risks_controls", "safety", "외부 변경·발송 또는 민감정보 처리 전에 필요한 권한과 사람 검토 위치가 확인되지 않았습니다."))

    if not steps:
        gaps.append(_gap("STEP_SEQUENCE_UNKNOWN", "steps", "branch", "업무 단계의 순서가 확인되지 않았습니다."))
    for decision_index, decision in enumerate(decisions):
        if not isinstance(decision, dict):
            gaps.append(_gap("DECISION_SCHEMA_INVALID", "decisions", "branch", "분기 정보 형식이 올바르지 않습니다.", "conflicting"))
            continue
        branches = decision.get("branches") or decision.get("outcomes")
        condition = decision.get("condition")
        if not condition or not isinstance(branches, list) or len(branches) < 2:
            gaps.append(_gap("BRANCH_CONDITION_UNKNOWN", f"decisions[{decision_index}]", "branch", "판단 조건과 두 개 이상의 분기 결과가 확인되지 않았습니다."))

    for field, code, message in (
        ("exceptions", "FAILURE_POLICY_UNKNOWN", "실패·예외 발생 시 처리 방식이 확인되지 않았습니다."),
        ("sla", "SLA_UNKNOWN", "기한 또는 허용 처리 시간이 확인되지 않았습니다."),
        ("success_criteria", "SUCCESS_CRITERIA_UNKNOWN", "완료 품질을 판단할 측정 기준이 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "quality", message, status))

    scope_in = {_plain_text(item) for item in (work.get("scope_in") or [])}
    scope_out = {_plain_text(item) for item in (work.get("scope_out") or [])}
    overlap = sorted(text for text in scope_in & scope_out if text)
    if overlap:
        gaps.append({**_gap("SCOPE_CONFLICT", "scope_in", "branch", "포함 범위와 제외 범위가 충돌합니다.", "conflicting"), "conflicting_values": overlap[:20]})

    gaps.sort(key=lambda item: (PRIORITY_ORDER.get(item["priority"], 99), item["reason_code"], item["target_paths"][0]))
    blocking = bool(gaps)
    result_status = "NEEDS_CLARIFICATION" if blocking else "READY_FOR_REVIEW"
    evaluation = {
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "session_id": work["session_id"],
        "revision": revision,
        "channel_mode": work.get("channel_mode"),
        "needs_clarification": blocking,
        "blocking_gap_count": len(gaps),
        "blocking_gaps": gaps,
        "question_policy": {"max_questions_per_round": 3, "priority_order": ["safety", "branch", "contract", "quality"]},
    }
    return {
        "ok": True,
        "status": result_status,
        "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": revision}],
        "completeness": evaluation,
        "trace_id": trace_id,
    }


class WorkCompletenessEvaluatorComponent(Component):
    display_name = "12 업무 정의 완전성 평가"
    description = "필수 계약, 위험, 분기 충돌을 규칙으로 평가해 blocking gap과 재질문 필요 여부를 반환합니다."
    icon = "ListChecks"
    name = "WorkCompletenessEvaluator"

    inputs = [DataInput(name="work_definition", display_name="WorkDefinition", input_types=["Data", "JSON"], required=True)]
    outputs = [Output(name="completeness", display_name="완전성 평가", method="build_evaluation", types=["Data"])]

    def build_evaluation(self) -> Data:
        result = evaluate_work_completeness(getattr(self, "work_definition", None))
        self.status = {"ok": result["ok"], "status": result["status"], "gap_count": result.get("completeness", {}).get("blocking_gap_count", 0)}
        return Data(data=result)

from __future__ import annotations

import copy
import hashlib
import json
import re
import uuid
from datetime import datetime, timedelta, timezone
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, MessageTextInput, Output, SecretStrInput
from lfx.schema import Data
from pymongo import MongoClient
from pymongo.errors import DuplicateKeyError, PyMongoError


ALLOWED_ANSWER_TYPES = {"text", "single_choice", "single_choice_with_text", "multi_choice", "boolean", "number"}
PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        return json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return {}


def _named(value: Any, *keys: str) -> dict[str, Any]:
    payload = _payload(value)
    for key in keys:
        nested = payload.get(key)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return payload


def _parse_now(value: Any) -> datetime:
    text = str(value or "").strip()
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00")) if text else datetime.now(timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    return str(getter() if callable(getter) else value or "")


def _get_path(root: Any, path: str) -> Any:
    current = root
    for part in [token for token in re.split(r"\.|\[|\]", path) if token]:
        if isinstance(current, dict):
            current = current.get(part)
        elif isinstance(current, list) and part.isdigit() and int(part) < len(current):
            current = current[int(part)]
        else:
            return None
    return current


def _is_confirmed(root: dict[str, Any], paths: list[str]) -> bool:
    if not paths:
        return False
    for path in paths:
        value = _get_path(root, path)
        if isinstance(value, dict) and value.get("status") == "confirmed" and "value" in value:
            continue
        if isinstance(value, list) and value:
            statuses = [((item.get("provenance") or {}).get("status")) for item in value if isinstance(item, dict)]
            if statuses and all(status == "confirmed" for status in statuses):
                continue
        return False
    return True


def _question_text(gap: dict[str, Any]) -> str:
    code = str(gap.get("reason_code") or "")
    templates = {
        "GOAL_UNKNOWN": "이 업무가 완료됐다고 판단할 수 있는 최종 결과는 무엇인가요?",
        "TRIGGER_UNKNOWN": "이 업무는 어떤 사건, 요청 또는 주기에 시작되나요?",
        "INPUT_CONTRACT_UNKNOWN": "업무에 반드시 들어오는 입력은 무엇이며 형식은 무엇인가요?",
        "OUTPUT_CONTRACT_UNKNOWN": "업무 결과는 무엇이며 누구 또는 어느 시스템에 전달되나요?",
        "PRIMARY_ACTOR_UNKNOWN": "이 업무의 주 수행자와 최종 책임자는 누구인가요?",
        "WRITE_APPROVAL_UNKNOWN": "데이터 저장·수정·발송 전에 담당자 확인이 필요한가요?",
        "SENSITIVE_REVIEW_UNKNOWN": "민감정보 처리 전후에 누가 확인하고 승인해야 하나요?",
        "STEP_SEQUENCE_UNKNOWN": "업무가 시작된 뒤 완료될 때까지의 단계를 순서대로 설명해 주세요.",
        "BRANCH_CONDITION_UNKNOWN": "어떤 조건에서 처리 경로가 나뉘며 각 경로의 결과는 무엇인가요? condition과 branches(2개 이상)를 가진 JSON object로 답해 주세요. 예: {\"condition\":\"오류가 있는가\",\"branches\":[\"예\",\"아니오\"]}",
        "FAILURE_POLICY_UNKNOWN": "조회·처리·전송이 실패하면 재시도, 담당자 전달, 종료 중 어떻게 처리해야 하나요?",
        "SLA_UNKNOWN": "이 업무의 완료 기한 또는 허용 처리 시간은 얼마인가요?",
        "SUCCESS_CRITERIA_UNKNOWN": "결과의 품질과 개선 효과를 어떤 수치나 기준으로 확인할까요?",
        "SCOPE_CONFLICT": "포함 범위와 제외 범위가 겹칩니다. 어느 범위로 확정할까요?",
    }
    return templates.get(code, str(gap.get("message") or "부족한 업무 정보를 알려 주세요."))


def build_clarification_batch(
    work_value: Any,
    completeness_value: Any,
    candidate_questions_value: Any = None,
    *,
    round_number: Any = 1,
    max_questions: Any = 3,
    expiry_minutes: Any = 60,
    now_utc: Any = "",
) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        completeness = _named(completeness_value, "completeness")
        candidate_payload = _payload(candidate_questions_value) if candidate_questions_value is not None else {}
        candidates = candidate_payload.get("questions") if isinstance(candidate_payload.get("questions"), list) else []
        supplied_round = int(round_number)
        question_limit = max(1, min(int(max_questions), 3))
        expiry = max(5, min(int(expiry_minutes), 1440))
        now = _parse_now(now_utc)
    except (TypeError, ValueError, json.JSONDecodeError):
        work, completeness, candidates, supplied_round, question_limit, expiry, now = {}, {}, [], -1, 3, 60, datetime.now(timezone.utc)
    processed = work.get("processed_answer_batches") if isinstance(work.get("processed_answer_batches"), list) else []
    processed_batch_ids = {
        str(item.get("batch_id") or "")
        for item in processed[:100]
        if isinstance(item, dict) and str(item.get("batch_id") or "")
    }
    expected_round = min(len(processed_batch_ids) + 1, 4)
    current_round = expected_round if supplied_round == 0 else supplied_round
    identity_fields = ("work_definition_id", "tenant_id", "owner_id", "session_id", "revision", "channel_mode")
    missing = [field for field in identity_fields if work.get(field) in (None, "")]
    # Round 4 is a non-interactive post-round gate: it may return
    # READY_FOR_REVIEW, but it must never create a fourth human question batch.
    if missing or current_round not in {1, 2, 3, 4}:
        code = "CLARIFICATION_ROUND_LIMIT" if current_round not in {1, 2, 3, 4} else "CLARIFICATION_INPUT_INVALID"
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": code, "message": "질문 batch 입력 또는 허용 회차가 유효하지 않습니다.", "retryable": False, "details": {"missing_fields": missing, "round_number": current_round}},
            "resume": None,
            "trace_id": trace_id,
        }
    if current_round != expected_round:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "CLARIFICATION_ROUND_SEQUENCE_MISMATCH",
                "message": "질문 회차가 처리 완료된 answer batch 이력과 일치하지 않습니다.",
                "retryable": False,
                "details": {
                    "supplied_round": supplied_round,
                    "expected_round": expected_round,
                    "processed_batch_count": len(processed_batch_ids),
                },
            },
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        work_revision = int(work["revision"])
        completeness_revision = int(completeness.get("revision", -1))
    except (TypeError, ValueError):
        work_revision, completeness_revision = -1, -2
    if completeness.get("work_definition_id") != work.get("work_definition_id") or completeness_revision != work_revision or work_revision < 0:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "CLARIFICATION_REVISION_MISMATCH", "message": "완전성 평가와 WorkDefinition revision이 다릅니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    gaps = completeness.get("blocking_gaps") if isinstance(completeness.get("blocking_gaps"), list) else []
    gaps = sorted((gap for gap in gaps if isinstance(gap, dict)), key=lambda gap: (PRIORITY_ORDER.get(str(gap.get("priority")), 99), str(gap.get("reason_code"))))
    candidate_by_code = {str(item.get("reason_code")): item for item in candidates if isinstance(item, dict) and item.get("reason_code")}
    questions: list[dict[str, Any]] = []
    seen_paths: set[tuple[str, ...]] = set()
    for gap in gaps:
        paths = [str(path)[:300] for path in gap.get("target_paths", []) if str(path).strip()][:10]
        if not paths or _is_confirmed(work, paths):
            continue
        path_key = tuple(sorted(paths))
        if path_key in seen_paths:
            continue
        model_question = candidate_by_code.get(str(gap.get("reason_code")), {})
        text = str(model_question.get("text") or _question_text(gap)).strip()[:1000]
        if not text:
            continue
        answer_type = str(model_question.get("answer_type") or "text")
        if answer_type not in ALLOWED_ANSWER_TYPES:
            answer_type = "text"
        choices = []
        for choice in model_question.get("choices", []) if isinstance(model_question.get("choices"), list) else []:
            safe = str(choice).strip()[:300]
            if safe and safe not in choices:
                choices.append(safe)
        if answer_type in {"single_choice", "single_choice_with_text", "multi_choice"} and not choices:
            answer_type = "text"
        if str(gap.get("reason_code")) == "BRANCH_CONDITION_UNKNOWN":
            answer_type = "text"
            choices = []
            if "condition" not in text or "branches" not in text:
                text = _question_text(gap)
        material = json.dumps({"work_definition_id": work["work_definition_id"], "revision": work_revision, "round": current_round, "reason": gap.get("reason_code"), "paths": paths}, sort_keys=True, ensure_ascii=False)
        questions.append(
            {
                "question_id": f"q-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}",
                "text": text,
                "target_paths": paths,
                "answer_type": answer_type,
                "choices": choices[:20],
                "required": bool(model_question.get("required", True)),
                "reason_code": str(gap.get("reason_code") or "CLARIFICATION_REQUIRED")[:100],
                "priority": str(gap.get("priority") or "quality"),
            }
        )
        seen_paths.add(path_key)
        if len(questions) >= question_limit:
            break

    if not questions:
        return {
            "ok": True,
            "status": "READY_FOR_REVIEW",
            "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": work_revision}],
            "clarification_batch": None,
            "trace_id": trace_id,
        }

    if current_round == 4:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": work_revision}],
            "clarification_batch": None,
            "error": {
                "code": "CLARIFICATION_ROUND_LIMIT",
                "message": "세 번의 보완 회차 후에도 필수 업무 계약이 남아 있어 자동 승인을 차단했습니다.",
                "retryable": False,
                "details": {"remaining_reason_codes": [question["reason_code"] for question in questions]},
            },
            "resume": None,
            "trace_id": trace_id,
        }

    canonical = json.dumps(questions, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    batch_material = f"{work['work_definition_id']}|{work['revision']}|{current_round}|{canonical}"
    batch_id = f"qb-{hashlib.sha256(batch_material.encode('utf-8')).hexdigest()[:24]}"
    batch = {
        "schema_version": "clarification-question-batch/v1",
        "batch_id": batch_id,
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "owner_id": work["owner_id"],
        "session_id": work["session_id"],
        "channel_mode": work["channel_mode"],
        "revision": work_revision,
        "round_number": current_round,
        "created_at": now.isoformat().replace("+00:00", "Z"),
        "expires_at": (now + timedelta(minutes=expiry)).isoformat().replace("+00:00", "Z"),
        "status": "WAITING_ANSWER",
        "questions": questions,
    }
    return {
        "ok": True,
        "status": "WAITING_ANSWER",
        "artifact_refs": [{"kind": "clarification_batch", "id": batch_id}],
        "clarification_batch": batch,
        "trace_id": trace_id,
    }


def persist_clarification_batch(
    result: dict[str, Any],
    *,
    mongodb_uri: Any,
    mongo_database: Any,
    collection_name: Any = "clarification_batches",
    timeout_ms: Any = 5000,
    client_factory: Any = MongoClient,
) -> dict[str, Any]:
    """Persist one immutable question contract; Answer Form may add answers later."""
    if not result.get("ok") or result.get("clarification_batch") is None:
        return result
    uri = _secret(mongodb_uri)
    database_name = str(mongo_database or "").strip()[:200]
    collection = str(collection_name or "clarification_batches").strip()[:200]
    try:
        timeout = max(1000, min(int(timeout_ms), 30_000))
    except (TypeError, ValueError):
        timeout = 5000
    if not uri or not database_name or not re.fullmatch(r"[A-Za-z0-9_.-]{1,200}", collection):
        failed = copy.deepcopy(result)
        failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_STORE_CONFIG_MISSING", "message": "질문 batch를 저장할 production MongoDB 설정이 필요합니다.", "retryable": False, "details": {}}, "resume": None})
        return failed
    batch = copy.deepcopy(result["clarification_batch"])
    contract_material = json.dumps({key: batch.get(key) for key in ("batch_id", "work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision", "round_number", "questions")}, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    contract_hash = hashlib.sha256(contract_material.encode("utf-8")).hexdigest()
    document = copy.deepcopy(batch)
    document["_id"] = "clarification-batch:" + hashlib.sha256(f"{batch['tenant_id']}|{batch['batch_id']}".encode("utf-8")).hexdigest()
    document["contract_sha256"] = contract_hash
    document["created_at"] = _parse_now(batch["created_at"])
    document["expires_at"] = _parse_now(batch["expires_at"])
    document["answers"] = None
    document["answer_idempotency_key"] = None
    document["answered_at"] = None
    client = None
    try:
        client = client_factory(uri, serverSelectionTimeoutMS=timeout, connectTimeoutMS=timeout, socketTimeoutMS=timeout, retryWrites=True)
        client.admin.command("ping")
        batches = client[database_name][collection]
        existing = batches.find_one({"_id": document["_id"]})
        if existing is not None:
            if str(existing.get("contract_sha256")) != contract_hash:
                failed = copy.deepcopy(result)
                failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_BATCH_CONFLICT", "message": "같은 batch ID에 다른 질문 계약이 이미 저장되어 있습니다.", "retryable": False, "details": {}}, "resume": None})
                return failed
            persisted = copy.deepcopy(result)
            persisted["store_result"] = {"persisted": True, "idempotent_replay": True, "contract_sha256": contract_hash}
            return persisted
        try:
            batches.insert_one(document)
        except DuplicateKeyError:
            existing = batches.find_one({"_id": document["_id"]})
            if existing is None or str(existing.get("contract_sha256")) != contract_hash:
                raise
        persisted = copy.deepcopy(result)
        persisted["store_result"] = {"persisted": True, "idempotent_replay": False, "contract_sha256": contract_hash}
        return persisted
    except PyMongoError as exc:
        failed = copy.deepcopy(result)
        failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_STORE_FAILED", "message": "질문 batch를 MongoDB에 저장하지 못했습니다.", "retryable": True, "details": {"exception_type": type(exc).__name__}}, "resume": None})
        return failed
    finally:
        if client is not None:
            client.close()


