from __future__ import annotations

"""Route a WorkDefinition around the clarification pause without local imports."""

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        return json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return {}


def _named(value: Any, key: str) -> dict[str, Any]:
    payload = _payload(value)
    nested = payload.get(key)
    return copy.deepcopy(nested) if isinstance(nested, dict) else payload


def route_work_clarification(work_value: Any, clarification_value: Any) -> dict[str, Any]:
    """Return one and only one route plus the payload for that route."""

    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        clarification = _payload(clarification_value)
    except (TypeError, ValueError, json.JSONDecodeError):
        work, clarification = {}, {}
    missing = [
        key
        for key in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision")
        if work.get(key) in (None, "")
    ]
    if missing:
        return {
            "ok": False,
            "status": "BLOCKED",
            "route": "blocked_path",
            "artifact_refs": [],
            "error": {
                "code": "WORK_ROUTE_INPUT_INVALID",
                "message": "Clarification 분기에 필요한 WorkDefinition 식별자가 없습니다.",
                "retryable": False,
                "details": {"fields": missing},
            },
            "resume": None,
            "trace_id": trace_id,
        }
    if not clarification.get("ok"):
        blocked = copy.deepcopy(clarification)
        blocked.update({"ok": False, "status": "BLOCKED", "route": "blocked_path"})
        blocked.setdefault("artifact_refs", [])
        blocked.setdefault(
            "error",
            {
                "code": "CLARIFICATION_ROUTE_BLOCKED",
                "message": "질문 생성 결과가 유효하지 않아 분기를 진행할 수 없습니다.",
                "retryable": False,
                "details": {},
            },
        )
        blocked.setdefault("resume", None)
        blocked.setdefault("trace_id", trace_id)
        return blocked

    batch = clarification.get("clarification_batch")
    if clarification.get("status") == "WAITING_ANSWER" and isinstance(batch, dict):
        identity_fields = ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode")
        mismatch = [key for key in identity_fields if str(batch.get(key) or "") != str(work.get(key) or "")]
        try:
            revision_matches = int(batch.get("revision", -1)) == int(work.get("revision", -2))
        except (TypeError, ValueError):
            revision_matches = False
        if mismatch or not revision_matches:
            return {
                "ok": False,
                "status": "BLOCKED",
                "route": "blocked_path",
                "artifact_refs": [],
                "error": {
                    "code": "CLARIFICATION_ROUTE_SCOPE_MISMATCH",
                    "message": "질문 batch와 저장된 WorkDefinition의 scope 또는 revision이 다릅니다.",
                    "retryable": False,
                    "details": {"fields": mismatch, "revision_matches": revision_matches},
                },
                "resume": None,
                "trace_id": trace_id,
            }
        routed = copy.deepcopy(clarification)
        routed["route"] = "clarification_path"
        routed["work_definition"] = copy.deepcopy(work)
        return routed

    if clarification.get("status") == "READY_FOR_REVIEW" and batch is None:
        return {
            "ok": True,
            "status": "READY_FOR_REVIEW",
            "route": "review_path",
            "artifact_refs": [
                {
                    "kind": "work_definition",
                    "id": work["work_definition_id"],
                    "revision": int(work["revision"]),
                }
            ],
            "work_definition": copy.deepcopy(work),
            "trace_id": trace_id,
        }

    return {
        "ok": False,
        "status": "BLOCKED",
        "route": "blocked_path",
        "artifact_refs": [],
        "error": {
            "code": "CLARIFICATION_ROUTE_STATE_INVALID",
            "message": "질문 생성 결과가 WAITING_ANSWER 또는 READY_FOR_REVIEW 계약과 일치하지 않습니다.",
            "retryable": False,
            "details": {"clarification_status": clarification.get("status")},
        },
        "resume": None,
        "trace_id": trace_id,
    }


class WorkClarificationRouterComponent(Component):
    display_name = "27 업무 보완 분기 Router"
    description = "질문 batch가 있으면 native/playground 보완 경로로, 없으면 review 경로로 정확히 하나만 실행합니다."
    icon = "GitBranch"
    name = "WorkClarificationRouter"

    inputs = [
        DataInput(name="work_definition", display_name="저장된 WorkDefinition", input_types=["Data", "JSON"], required=True),
        DataInput(name="clarification_result", display_name="질문 Batch 생성 결과", input_types=["Data", "JSON"], required=True),
    ]
    outputs = [
        Output(
            name="clarification_path",
            display_name="질문 필요",
            method="route_branch",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="review_path",
            display_name="바로 Review",
            method="route_branch",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="blocked_path",
            display_name="차단됨",
            method="route_branch",
            types=["Data"],
            group_outputs=True,
        ),
    ]

    def route_branch(self) -> Data:
        result = route_work_clarification(
            getattr(self, "work_definition", None),
            getattr(self, "clarification_result", None),
        )
        selected = str(result.get("route") or "blocked_path")
        for output_name in ("clarification_path", "review_path", "blocked_path"):
            if output_name != selected:
                self.stop(output_name)
        self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": selected}
        return Data(data=result)

from __future__ import annotations

import copy
import hashlib
import json
import math
import re
import uuid
from datetime import datetime, timezone
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.parse import quote, urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

from lfx.custom import Component
from lfx.io import DataInput, DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput
from lfx.schema import Data
from pymongo import MongoClient
from pymongo.errors import PyMongoError


ALLOWED_CHANNELS = {"native_hitl", "playground"}
ALLOWED_ANSWER_TYPES = {"text", "single_choice", "single_choice_with_text", "multi_choice", "boolean", "number"}
MAX_ANSWER_VALUE_BYTES = 64 * 1024
MAX_FREE_TEXT_CHARS = 16_000


class _NoRedirectHandler(HTTPRedirectHandler):
    def redirect_request(self, req: Any, fp: Any, code: int, msg: str, headers: Any, newurl: str) -> None:
        return None


_ANSWER_API_OPENER = build_opener(_NoRedirectHandler).open


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        return json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return {}


def _named(value: Any, *keys: str) -> dict[str, Any]:
    payload = _payload(value)
    for key in keys:
        nested = payload.get(key)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return payload


def _utc(value: Any) -> datetime:
    text = str(value or "").strip()
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00")) if text else datetime.now(timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _failure(code: str, message: str, trace_id: str, details: dict[str, Any] | None = None, *, retryable: bool = False) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
    }


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _normalize_answer_value(question: dict[str, Any], value: Any) -> Any:
    answer_type = str(question.get("answer_type") or "text")
    if answer_type not in ALLOWED_ANSWER_TYPES:
        raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    raw_choices = question.get("choices", [])
    if not isinstance(raw_choices, list):
        raise ValueError("ANSWER_CHOICE_INVALID")
    choices = [str(item) for item in raw_choices if isinstance(item, str)]
    required = bool(question.get("required", True))
    if value in (None, "", []):
        if required:
            raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
        return None
    if answer_type == "text":
        if not isinstance(value, str) or len(value) > MAX_FREE_TEXT_CHARS:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized: Any = value
    elif answer_type == "single_choice":
        if not isinstance(value, str) or value not in choices:
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = value
    elif answer_type == "single_choice_with_text":
        if isinstance(value, str) and value in choices:
            normalized = {"choice": value, "text": ""}
        elif isinstance(value, dict) and set(value) <= {"choice", "text"}:
            choice = value.get("choice")
            text = value.get("text", "")
            if not isinstance(choice, str) or not isinstance(text, str) or len(text) > MAX_FREE_TEXT_CHARS:
                raise ValueError("ANSWER_VALUE_TYPE_INVALID")
            if choice == "__other__":
                if not text.strip():
                    raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
            elif choice not in choices:
                raise ValueError("ANSWER_CHOICE_INVALID")
            normalized = {"choice": choice, "text": text}
        else:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    elif answer_type == "multi_choice":
        if not isinstance(value, list) or not value or any(not isinstance(item, str) or item not in choices for item in value):
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = list(dict.fromkeys(value))
    elif answer_type == "boolean":
        if not isinstance(value, bool):
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized = value
    else:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)) or abs(float(value)) > 1e15:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized = value
    if len(_canonical(normalized).encode("utf-8")) > MAX_ANSWER_VALUE_BYTES:
        raise ValueError("ANSWER_VALUE_TOO_LARGE")
    return normalized


def load_work_answers(
    work_value: Any,
    batch_value: Any,
    *,
    channel_mode: Any,
    native_form_payload: Any = None,
    playground_payload: Any = None,
    human_action: Any = "",
    now_utc: Any = "",
) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        batch = _named(batch_value, "clarification_batch")
        native = _payload(native_form_payload)
        playground = _payload(playground_payload)
        now = _utc(now_utc)
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("ANSWER_PAYLOAD_INVALID", "답변 payload를 해석할 수 없습니다.", trace_id)

    channel = str(channel_mode or "").strip().lower()
    if channel not in ALLOWED_CHANNELS:
        return _failure("ANSWER_CHANNEL_INVALID", "지원하지 않는 답변 channel입니다.", trace_id, {"allowed": sorted(ALLOWED_CHANNELS)})
    native_present = bool(native)
    playground_present = bool(playground)
    if native_present and playground_present:
        return _failure("ANSWER_CHANNEL_MIXED", "F10 form 답변과 F11 Playground 답변을 한 실행에서 함께 사용할 수 없습니다.", trace_id)
    if (channel == "native_hitl" and not native_present) or (channel == "playground" and not playground_present):
        return _failure("ANSWER_CHANNEL_PAYLOAD_MISSING", "선택한 channel의 답변 payload가 없습니다.", trace_id)
    if (channel == "native_hitl" and playground_present) or (channel == "playground" and native_present):
        return _failure("ANSWER_CHANNEL_MISMATCH", "답변 payload가 WorkDefinition channel과 일치하지 않습니다.", trace_id)
    if any(str(work.get(key, "")) != str(batch.get(key, "")) for key in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode")):
        return _failure("ANSWER_BATCH_IDENTITY_MISMATCH", "질문 batch와 WorkDefinition 식별자 또는 channel이 다릅니다.", trace_id)
    if str(work.get("channel_mode")) != channel:
        return _failure("ANSWER_WORK_CHANNEL_MISMATCH", "기존 작업의 channel을 다른 channel로 전환할 수 없습니다.", trace_id)

    selected = native if channel == "native_hitl" else playground
    selected_channel = str(selected.get("channel_mode") or channel).strip().lower()
    command = str(selected.get("command") or selected.get("action") or human_action or "").strip().lower()
    if selected_channel != channel or command != "submit_answers":
        return _failure("ANSWER_ACTION_INVALID", "답변 제출은 현재 channel의 submit_answers action이어야 합니다.", trace_id, {"command": command})
    if channel == "native_hitl" and str(human_action or "").strip().lower() != "submit_answers":
        return _failure("ANSWER_HITL_ACTION_REQUIRED", "F10에서는 Human Input의 submit_answers action 확인이 필요합니다.", trace_id)

    expected_identity = {
        "work_definition_id": work.get("work_definition_id"),
        "batch_id": batch.get("batch_id"),
        "session_id": work.get("session_id"),
    }
    identity_mismatch = [key for key, expected in expected_identity.items() if str(selected.get(key, "")) != str(expected)]
    if identity_mismatch:
        return _failure("ANSWER_PAYLOAD_IDENTITY_MISMATCH", "답변 payload가 현재 작업·batch·session과 일치하지 않습니다.", trace_id, {"fields": identity_mismatch})
    try:
        submitted_revision = int(selected.get("expected_revision"))
        work_revision = int(work.get("revision"))
        batch_revision = int(batch.get("revision"))
    except (TypeError, ValueError):
        return _failure("ANSWER_REVISION_INVALID", "expected_revision이 올바르지 않습니다.", trace_id)
    if submitted_revision != work_revision or batch_revision != work_revision:
        return _failure("REVISION_CONFLICT", "답변 대상 revision이 최신 WorkDefinition과 다릅니다.", trace_id, {"expected_revision": submitted_revision, "current_revision": work_revision})
    batch_status = str(batch.get("status"))
    if batch_status not in {"WAITING_ANSWER", "ANSWERED"}:
        return _failure("ANSWER_BATCH_NOT_PENDING", "답변을 기다리는 batch가 아닙니다.", trace_id)
    try:
        answer_deadline = _utc(batch.get("answer_deadline_at") or batch.get("expires_at"))
    except (TypeError, ValueError):
        return _failure("ANSWER_BATCH_EXPIRY_INVALID", "질문 batch의 만료 시각이 올바르지 않습니다.", trace_id)
    if batch_status == "ANSWERED":
        # Store/API modes authenticate the persisted submission. A resume may
        # happen after the answer deadline; what matters is that the durable
        # submitted_at timestamp was on time.
        try:
            durable_submitted_at = _utc(selected.get("submitted_at"))
        except (TypeError, ValueError):
            return _failure("ANSWER_SUBMITTED_AT_INVALID", "저장된 답변 제출 시각이 올바르지 않습니다.", trace_id)
        if durable_submitted_at >= answer_deadline:
            return _failure("ANSWER_BATCH_EXPIRED", "답변이 질문 batch 마감 이후 제출되었습니다.", trace_id)
    elif now >= answer_deadline:
        # Direct-payload mode is intentionally test/Playground-only and cannot
        # backdate an untrusted submitted_at value to bypass the deadline.
        return _failure("ANSWER_BATCH_EXPIRED", "질문 batch가 만료되었습니다.", trace_id)

    idempotency_key = str(selected.get("idempotency_key") or "").strip()[:300]
    if not idempotency_key:
        return _failure("ANSWER_IDEMPOTENCY_KEY_REQUIRED", "중복 제출 방지를 위한 idempotency_key가 필요합니다.", trace_id)
    raw_answers = selected.get("answers")
    if isinstance(raw_answers, dict):
        raw_answers = [{"question_id": key, "value": value} for key, value in raw_answers.items()]
    if not isinstance(raw_answers, list):
        return _failure("ANSWER_LIST_INVALID", "answers는 question_id와 value를 가진 목록 또는 object여야 합니다.", trace_id)

    question_by_id = {str(item.get("question_id")): item for item in batch.get("questions", []) if isinstance(item, dict) and item.get("question_id")}
    normalized_answers: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in raw_answers[:100]:
        if not isinstance(item, dict):
            return _failure("ANSWER_ITEM_INVALID", "각 답변은 object여야 합니다.", trace_id)
        question_id = str(item.get("question_id") or "")
        if question_id not in question_by_id or question_id in seen:
            return _failure("ANSWER_QUESTION_INVALID", "알 수 없거나 중복된 question_id가 있습니다.", trace_id, {"question_id": question_id})
        question = question_by_id[question_id]
        try:
            value = _normalize_answer_value(question, copy.deepcopy(item.get("value")))
        except ValueError as exc:
            code = str(exc)
            messages = {
                "ANSWER_REQUIRED_VALUE_MISSING": "필수 질문의 답변이 없습니다.",
                "ANSWER_CHOICE_INVALID": "선택형 답변이 허용된 선택지와 일치하지 않습니다.",
                "ANSWER_VALUE_TYPE_INVALID": "답변 형식이 질문의 answer_type과 일치하지 않습니다.",
                "ANSWER_VALUE_TOO_LARGE": "답변 값이 허용 크기를 초과했습니다.",
            }
            return _failure(code, messages.get(code, "답변 값이 유효하지 않습니다."), trace_id, {"question_id": question_id})
        normalized_answers.append(
            {
                "question_id": question_id,
                "value": value,
                "target_paths": copy.deepcopy(question.get("target_paths", [])),
                "reason_code": question.get("reason_code"),
                "resolve_conflict": bool(item.get("resolve_conflict", False)),
                "evidence_turn_id": str(item.get("evidence_turn_id") or selected.get("turn_id") or f"answer-{question_id}")[:200],
            }
        )
        seen.add(question_id)
    missing_required = [question_id for question_id, question in question_by_id.items() if question.get("required", True) and question_id not in seen]
    if missing_required:
        return _failure("ANSWER_REQUIRED_QUESTIONS_MISSING", "필수 질문 일부가 제출되지 않았습니다.", trace_id, {"question_ids": missing_required})

    receipt_material = json.dumps({"batch_id": batch["batch_id"], "idempotency_key": idempotency_key, "answers": normalized_answers}, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    submission = {
        "schema_version": "work-answer-submission/v1",
        "submission_id": f"answer-{hashlib.sha256(receipt_material.encode('utf-8')).hexdigest()[:24]}",
        "idempotency_key": idempotency_key,
        "channel_mode": channel,
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "session_id": work["session_id"],
        "batch_id": batch["batch_id"],
        "expected_revision": work_revision,
        "answers": normalized_answers,
        "submitted_at": str(selected.get("submitted_at") or now.isoformat().replace("+00:00", "Z")),
        "payload_sha256": hashlib.sha256(receipt_material.encode("utf-8")).hexdigest(),
    }
    return {
        "ok": True,
        "status": "MERGING",
        "artifact_refs": [{"kind": "answer_submission", "id": submission["submission_id"]}],
        "answer_submission": submission,
        "trace_id": trace_id,
    }


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    return str(getter() if callable(getter) else value or "")


def _validate_loaded_batch(
    work: dict[str, Any],
    stored: dict[str, Any],
    *,
    channel_mode: Any,
    native_form_payload: Any,
    playground_payload: Any,
    human_action: Any,
    now_utc: Any,
    source: str,
) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    canonical_batch = copy.deepcopy(stored)
    canonical_batch.pop("_id", None)
    canonical_batch["created_at"] = str(canonical_batch.get("created_at") or "")
    canonical_batch["expires_at"] = str(canonical_batch.get("expires_at") or "")
    canonical_batch["answer_deadline_at"] = str(
        canonical_batch.get("answer_deadline_at") or canonical_batch.get("expires_at") or ""
    )
    channel = str(channel_mode or "").lower()
    if channel == "native_hitl":
        if str(canonical_batch.get("status")) != "ANSWERED" or canonical_batch.get("answers") is None:
            return _failure("ANSWER_FORM_NOT_SUBMITTED", "Answer Form의 자유서술 답변이 아직 저장되지 않았습니다.", trace_id)
        try:
            supplied_ref = _payload(native_form_payload)
        except (TypeError, ValueError, json.JSONDecodeError):
            return _failure("ANSWER_FORM_REFERENCE_INVALID", "Answer Form 참조 payload를 해석할 수 없습니다.", trace_id)
        native_payload = {
            "channel_mode": "native_hitl",
            "command": "submit_answers",
            "work_definition_id": work["work_definition_id"],
            "batch_id": canonical_batch.get("batch_id"),
            "session_id": work["session_id"],
            "expected_revision": canonical_batch.get("revision"),
            "idempotency_key": canonical_batch.get("answer_idempotency_key"),
            "answers": copy.deepcopy(canonical_batch.get("answers")),
            "submitted_at": str(canonical_batch.get("answered_at") or ""),
            "turn_id": str(canonical_batch.get("answer_turn_id") or supplied_ref.get("turn_id") or ""),
        }
        playground_payload = None
    else:
        native_payload = None
    # Human Input branch outputs carry the rendered prompt, not the action_id.
    # Reaching this store/API loader through a non-empty connected branch is the
    # execution proof; the persisted payload itself is forced to
    # command=submit_answers above. Direct-payload mode does not pass through
    # this adapter and still requires the literal action_id.
    canonical_human_action = "submit_answers" if channel == "native_hitl" and str(human_action or "").strip() else human_action
    result = load_work_answers(
        work,
        canonical_batch,
        channel_mode=channel,
        native_form_payload=native_payload,
        playground_payload=playground_payload,
        human_action=canonical_human_action,
        now_utc=now_utc,
    )
    if result.get("ok"):
        result["store_result"] = {"batch_loaded": True, "source": source}
    return result


def _batch_from_api_payload(payload: dict[str, Any]) -> dict[str, Any]:
    if isinstance(payload.get("clarification_batch"), dict):
        batch = copy.deepcopy(payload["clarification_batch"])
    elif isinstance(payload.get("batch"), dict):
        batch = copy.deepcopy(payload["batch"])
    else:
        batch = copy.deepcopy(payload)
    answer = payload.get("answer_submission") if isinstance(payload.get("answer_submission"), dict) else None
    if answer is None and isinstance(batch.get("answer_submission"), dict):
        answer = batch.get("answer_submission")
    if answer is not None:
        batch["answers"] = copy.deepcopy(answer.get("answers"))
        batch["answer_idempotency_key"] = answer.get("idempotency_key")
        batch["answered_at"] = answer.get("submitted_at")
        batch["answer_turn_id"] = answer.get("turn_id")
        batch["status"] = "ANSWERED"
    elif str(batch.get("status")) in {"ANSWERED_PENDING_RESUME", "RESUMED"} and batch.get("answers") is not None:
        batch["status"] = "ANSWERED"
    batch.pop("answer_submission", None)
    return batch


def load_work_answers_from_companion_api(
    work_value: Any,
    batch_value: Any,
    *,
    channel_mode: Any,
    native_form_payload: Any = None,
    playground_payload: Any = None,
    human_action: Any = "",
    now_utc: Any = "",
    answer_api_base_url: Any,
    answer_api_token: Any,
    timeout_seconds: Any = 10,
    max_response_bytes: Any = 1_000_000,
    opener: Any = None,
) -> dict[str, Any]:
    """Fetch one authenticated Answer Form record without relying on HITL action payload text."""
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        batch_ref = _named(batch_value, "clarification_batch")
        base_url = str(answer_api_base_url or "").strip().rstrip("/")
        token = _secret(answer_api_token)
        timeout = max(1, min(int(timeout_seconds), 60))
        response_limit = max(1_024, min(int(max_response_bytes), 5_000_000))
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("ANSWER_API_INPUT_INVALID", "Answer Form API 조회 입력을 해석할 수 없습니다.", trace_id)
    parsed = urlsplit(base_url)
    if parsed.scheme != "https" or not parsed.netloc or parsed.username or parsed.password or not token:
        return _failure("ANSWER_API_CONFIG_INVALID", "Answer Form API는 credential이 없는 HTTPS base URL과 인증 token이 필요합니다.", trace_id)
    batch_id = str(batch_ref.get("batch_id") or "")
    work_id = str(work.get("work_definition_id") or "")
    if not batch_id or not work_id or not work.get("tenant_id") or not work.get("owner_id"):
        return _failure("ANSWER_BATCH_REFERENCE_INVALID", "Answer Form API 조회에 필요한 tenant/owner/work/batch 식별자가 없습니다.", trace_id)
    endpoint = f"{base_url}/api/work-definitions/{quote(work_id, safe='')}/question-batches/{quote(batch_id, safe='')}"
    request = Request(
        endpoint,
        headers={
            "Accept": "application/json",
            "Authorization": f"Bearer {token}",
            "X-Tenant-ID": str(work["tenant_id"]),
            "X-Actor-ID": str(work["owner_id"]),
        },
        method="GET",
    )
    try:
        open_request = opener or _ANSWER_API_OPENER
        with open_request(request, timeout=timeout) as response:
            final_url = str(getattr(response, "geturl", lambda: endpoint)())
            if urlsplit(final_url).scheme != "https":
                return _failure("ANSWER_API_REDIRECT_INVALID", "Answer Form API가 허용되지 않은 URL로 이동했습니다.", trace_id)
            response_headers = getattr(response, "headers", {})
            content_type = str(response_headers.get("Content-Type", "") or "").lower()
            if content_type and "json" not in content_type:
                return _failure("ANSWER_API_SCHEMA_INVALID", "Answer Form API 응답 Content-Type이 JSON이 아닙니다.", trace_id)
            length_text = str(response_headers.get("Content-Length", "") or "")
            if length_text.isdigit() and int(length_text) > response_limit:
                return _failure("ANSWER_API_RESPONSE_TOO_LARGE", "Answer Form API 응답이 허용 크기를 초과했습니다.", trace_id)
            raw = response.read(response_limit + 1)
        if len(raw) > response_limit:
            return _failure("ANSWER_API_RESPONSE_TOO_LARGE", "Answer Form API 응답이 허용 크기를 초과했습니다.", trace_id)
        decoded = json.loads(raw.decode("utf-8"))
        if not isinstance(decoded, dict):
            return _failure("ANSWER_API_SCHEMA_INVALID", "Answer Form API 응답은 JSON object여야 합니다.", trace_id)
        stored = _batch_from_api_payload(decoded)
        return _validate_loaded_batch(
            work,
            stored,
            channel_mode=channel_mode,
            native_form_payload=native_form_payload,
            playground_payload=playground_payload,
            human_action=human_action,
            now_utc=now_utc,
            source="companion_api",
        )
    except HTTPError as exc:
        retryable = int(getattr(exc, "code", 0)) >= 500 or int(getattr(exc, "code", 0)) == 429
        return _failure("ANSWER_API_HTTP_FAILED", "Answer Form API가 조회 요청을 완료하지 못했습니다.", trace_id, {"http_status": int(getattr(exc, "code", 0))}, retryable=retryable)
    except (URLError, TimeoutError, OSError) as exc:
        return _failure("ANSWER_API_UNAVAILABLE", "Answer Form API에 연결할 수 없습니다.", trace_id, {"exception_type": type(exc).__name__}, retryable=True)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _failure("ANSWER_API_SCHEMA_INVALID", "Answer Form API 응답을 UTF-8 JSON으로 해석할 수 없습니다.", trace_id)


def load_work_answers_from_store(
    work_value: Any,
    batch_value: Any,
    *,
    channel_mode: Any,
    native_form_payload: Any = None,
    playground_payload: Any = None,
    human_action: Any = "",
    now_utc: Any = "",
    mongodb_uri: Any,
    mongo_database: Any,
    collection_name: Any = "clarification_batches",
    timeout_ms: Any = 5000,
    client_factory: Any = MongoClient,
) -> dict[str, Any]:
    """Load the canonical batch (and F10 form answers) from durable MongoDB."""
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        batch_ref = _named(batch_value, "clarification_batch")
        uri = _secret(mongodb_uri)
        database_name = str(mongo_database or "").strip()[:200]
        collection = str(collection_name or "clarification_batches").strip()[:200]
        timeout = max(1000, min(int(timeout_ms), 30_000))
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("ANSWER_STORE_INPUT_INVALID", "답변 저장소 조회 입력을 해석할 수 없습니다.", trace_id)
    if not uri or not database_name or not re.fullmatch(r"[A-Za-z0-9_.-]{1,200}", collection):
        return _failure("ANSWER_STORE_CONFIG_MISSING", "답변을 조회할 production MongoDB 설정이 필요합니다.", trace_id)
    batch_id = str(batch_ref.get("batch_id") or "")
    if not batch_id or not work.get("tenant_id") or not work.get("work_definition_id"):
        return _failure("ANSWER_BATCH_REFERENCE_INVALID", "답변 조회에 필요한 tenant/work/batch 식별자가 없습니다.", trace_id)
    client = None
    try:
        client = client_factory(uri, serverSelectionTimeoutMS=timeout, connectTimeoutMS=timeout, socketTimeoutMS=timeout, retryWrites=True)
        client.admin.command("ping")
        stored = client[database_name][collection].find_one({"tenant_id": work["tenant_id"], "owner_id": work.get("owner_id"), "work_definition_id": work["work_definition_id"], "batch_id": batch_id})
        if stored is None:
            return _failure("ANSWER_BATCH_NOT_FOUND", "저장된 질문 batch를 찾을 수 없습니다.", trace_id)
        return _validate_loaded_batch(
            work,
            _batch_from_api_payload(stored),
            channel_mode=channel_mode,
            native_form_payload=native_form_payload,
            playground_payload=playground_payload,
            human_action=human_action,
            now_utc=now_utc,
            source="clarification_batches",
        )
    except PyMongoError as exc:
        return _failure("ANSWER_STORE_READ_FAILED", "질문 batch 또는 답변을 MongoDB에서 읽지 못했습니다.", trace_id, {"exception_type": type(exc).__name__}, retryable=True)
    finally:
        if client is not None:
            client.close()


class WorkAnswerLoaderComponent(Component):
    display_name = "14 업무 답변 Loader"
    description = "MongoDB 또는 인증된 companion API에서 F10 form 답변을 다시 읽고, F11 payload와 함께 batch/session/revision/channel 계약을 검증합니다."
    icon = "Import"
    name = "WorkAnswerLoader"

    inputs = [
        DataInput(name="work_definition", display_name="WorkDefinition", input_types=["Data", "JSON"], required=True),
        DataInput(name="clarification_batch", display_name="질문 Batch", input_types=["Data", "JSON"], required=True),
        DataInput(
            name="route_trigger",
            display_name="Runtime State Persist Trigger",
            input_types=["Data", "JSON"],
            required=False,
            advanced=True,
            info="F10에서 MERGING runtime state 저장 완료를 보장하는 실행 의존성입니다.",
        ),
        DropdownInput(name="channel_mode", display_name="답변 Channel", options=["native_hitl", "playground"], value="native_hitl"),
        DataInput(name="native_form_payload", display_name="F10 Answer Form Payload", input_types=["Data", "JSON"], required=False),
        DataInput(name="playground_payload", display_name="F11 Playground Payload", input_types=["Data", "Message", "JSON"], required=False),
        MessageTextInput(name="human_action", display_name="F10 Human Input Action", value="", required=False),
        MessageTextInput(name="now_utc", display_name="검증 기준 시각", value="", advanced=True),
        DropdownInput(name="answer_source_mode", display_name="답변 조회 Source", options=["mongodb", "companion_api", "direct_payload"], value="mongodb", info="direct_payload는 자동 fallback이 아닌 Flow contract test용 명시 모드입니다."),
        SecretStrInput(name="mongodb_uri", display_name="MongoDB URI", required=False),
        MessageTextInput(name="mongo_database", display_name="MongoDB Database", value="", required=False),
        MessageTextInput(name="collection_name", display_name="질문 Batch Collection", value="clarification_batches", advanced=True),
        IntInput(name="timeout_ms", display_name="MongoDB Timeout(ms)", value=5000, advanced=True),
        MessageTextInput(name="answer_api_base_url", display_name="Answer Form API HTTPS Base URL", value="", required=False),
        SecretStrInput(name="answer_api_token", display_name="Answer Form API Token", required=False),
        IntInput(name="answer_api_timeout_seconds", display_name="Answer API Timeout(s)", value=10, advanced=True),
        IntInput(name="answer_api_max_response_bytes", display_name="Answer API 최대 응답 Byte", value=1000000, advanced=True),
    ]
    outputs = [Output(name="answer_submission", display_name="검증된 답변", method="build_submission", types=["Data"])]

    def build_submission(self) -> Data:
        common = {
            "channel_mode": getattr(self, "channel_mode", "native_hitl"),
            "native_form_payload": getattr(self, "native_form_payload", None),
            "playground_payload": getattr(self, "playground_payload", None),
            "human_action": getattr(self, "human_action", ""),
            "now_utc": getattr(self, "now_utc", ""),
        }
        source_mode = getattr(self, "answer_source_mode", "mongodb")
        if source_mode == "companion_api":
            result = load_work_answers_from_companion_api(
                getattr(self, "work_definition", None),
                getattr(self, "clarification_batch", None),
                **common,
                answer_api_base_url=getattr(self, "answer_api_base_url", ""),
                answer_api_token=getattr(self, "answer_api_token", ""),
                timeout_seconds=getattr(self, "answer_api_timeout_seconds", 10),
                max_response_bytes=getattr(self, "answer_api_max_response_bytes", 1000000),
                opener=_ANSWER_API_OPENER,
            )
        elif source_mode == "direct_payload":
            result = load_work_answers(
                getattr(self, "work_definition", None),
                getattr(self, "clarification_batch", None),
                **common,
            )
            if result.get("ok"):
                result["store_result"] = {"batch_loaded": False, "source": "direct_payload"}
        else:
            result = load_work_answers_from_store(
                getattr(self, "work_definition", None),
                getattr(self, "clarification_batch", None),
                **common,
                mongodb_uri=getattr(self, "mongodb_uri", ""),
                mongo_database=getattr(self, "mongo_database", ""),
                collection_name=getattr(self, "collection_name", "clarification_batches"),
                timeout_ms=getattr(self, "timeout_ms", 5000),
                client_factory=MongoClient,
            )
        self.status = {"ok": result["ok"], "status": result["status"], "channel_mode": getattr(self, "channel_mode", "native_hitl")}
        return Data(data=result)

from __future__ import annotations

import copy
import hashlib
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}
LIST_FIELDS = {
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "decisions",
    "exceptions",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "assumptions",
    "unresolved",
}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        return json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return {}


def _named(value: Any, *keys: str) -> dict[str, Any]:
    payload = _payload(value)
    for key in keys:
        nested = payload.get(key)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return payload


def _failure(code: str, message: str, trace_id: str, details: dict[str, Any] | None = None) -> dict[str, Any]:
    return {"ok": False, "status": "BLOCKED", "artifact_refs": [], "error": {"code": code, "message": message, "retryable": False, "details": details or {}}, "resume": None, "trace_id": trace_id}


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _same(left: Any, right: Any) -> bool:
    return _canonical(left) == _canonical(right)


def _path_tokens(path: str) -> list[str | int]:
    tokens: list[str | int] = []
    for key, index in re.findall(r"([A-Za-z_][A-Za-z0-9_-]*)|\[(\d+)\]", path):
        tokens.append(int(index) if index else key)
    return tokens


def _get_path(root: Any, tokens: list[str | int]) -> Any:
    current = root
    for token in tokens:
        if isinstance(token, int) and isinstance(current, list) and token < len(current):
            current = current[token]
        elif isinstance(token, str) and isinstance(current, dict):
            current = current.get(token)
        else:
            return None
    return current


def _set_path(root: dict[str, Any], tokens: list[str | int], value: Any) -> bool:
    if not tokens or not isinstance(tokens[0], str):
        return False
    current: Any = root
    for position, token in enumerate(tokens[:-1]):
        next_token = tokens[position + 1]
        if isinstance(token, str):
            if not isinstance(current, dict):
                return False
            if token not in current or current[token] is None:
                current[token] = [] if isinstance(next_token, int) else {}
            current = current[token]
        else:
            if not isinstance(current, list) or token < 0 or token >= len(current):
                return False
            current = current[token]
    last = tokens[-1]
    if isinstance(last, str) and isinstance(current, dict):
        current[last] = value
        return True
    if isinstance(last, int) and isinstance(current, list) and 0 <= last < len(current):
        current[last] = value
        return True
    return False


def _evidence(existing: Any, turn_id: str) -> list[str]:
    current = existing if isinstance(existing, list) else []
    result: list[str] = []
    for item in current + [turn_id]:
        text = str(item or "").strip()[:200]
        if text and text not in result:
            result.append(text)
    return result[:100]


def _merge_fact(current: Any, incoming: Any, *, revision: int, evidence_turn_id: str, resolve_conflict: bool) -> tuple[dict[str, Any], bool]:
    fact = copy.deepcopy(current) if isinstance(current, dict) and current.get("status") in FACT_STATUSES and "value" in current else {
        "value": copy.deepcopy(current) if current not in (None, "") else None,
        "status": "unknown" if current in (None, "") else "inferred",
        "evidence_turn_ids": [],
        "confidence": 0.0 if current in (None, "") else 0.7,
        "last_updated_revision": max(0, revision - 1),
    }
    old_value = copy.deepcopy(fact.get("value"))
    evidence = _evidence(fact.get("evidence_turn_ids"), evidence_turn_id)
    if fact.get("status") in {"confirmed", "conflicting"} and not _same(old_value, incoming) and not resolve_conflict:
        candidates = copy.deepcopy(fact.get("conflicting_values", [])) if isinstance(fact.get("conflicting_values"), list) else []
        for candidate in (old_value, copy.deepcopy(incoming)):
            if not any(_same(candidate, known) for known in candidates):
                candidates.append(candidate)
        return {
            "value": old_value,
            "status": "conflicting",
            "conflicting_values": candidates[:20],
            "evidence_turn_ids": evidence,
            "confidence": 0.0,
            "last_updated_revision": revision,
        }, True
    return {
        "value": copy.deepcopy(incoming),
        "status": "confirmed",
        "evidence_turn_ids": evidence,
        "confidence": 1.0,
        "last_updated_revision": revision,
    }, False


def _confirmed_list(value: Any, *, path: str, revision: int, evidence_turn_id: str) -> list[dict[str, Any]]:
    raw_items = value if isinstance(value, list) else [value]
    result: list[dict[str, Any]] = []
    for index, item in enumerate(raw_items[:500]):
        record = copy.deepcopy(item) if isinstance(item, dict) else {"value": copy.deepcopy(item)}
        identity = record.get("id") or record.get("name") or record.get("label") or record.get("title") or record.get("value") or index
        identity_material = f"{path}|{identity}"
        record.setdefault("id", f"{path.rstrip('s') or 'item'}-{hashlib.sha256(identity_material.encode('utf-8')).hexdigest()[:16]}")
        previous = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
        record["provenance"] = {
            "status": "confirmed",
            "evidence_turn_ids": _evidence(previous.get("evidence_turn_ids"), evidence_turn_id),
            "confidence": 1.0,
            "last_updated_revision": revision,
        }
        result.append(record)
    return result


def _merge_decision(
    current: Any,
    incoming: Any,
    *,
    revision: int,
    evidence_turn_id: str,
    resolve_conflict: bool,
) -> tuple[dict[str, Any], bool]:
    if isinstance(incoming, str):
        if len(incoming) > 20_000:
            raise ValueError("decision answer is too large")
        try:
            incoming = json.loads(incoming)
        except json.JSONDecodeError as exc:
            raise ValueError("decision answer must be a JSON object") from exc
    if not isinstance(incoming, dict):
        raise ValueError("decision answer must be a JSON object")
    condition = str(incoming.get("condition") or "").strip()[:2_000]
    branches = incoming.get("branches") if isinstance(incoming.get("branches"), list) else incoming.get("outcomes")
    if not condition or not isinstance(branches, list) or not 2 <= len(branches) <= 20:
        raise ValueError("decision answer requires condition and 2 to 20 branches")
    normalized_branches: list[dict[str, Any]] = []
    for index, branch in enumerate(branches):
        record = copy.deepcopy(branch) if isinstance(branch, dict) else {"label": str(branch)}
        label = str(record.get("label") or record.get("name") or record.get("value") or "").strip()[:500]
        if not label:
            raise ValueError("every decision branch requires a label")
        record["label"] = label
        record.setdefault("branch_id", f"branch-{index + 1}")
        normalized_branches.append(record)
    base = copy.deepcopy(current) if isinstance(current, dict) else {}
    previous_contract = {"condition": base.get("condition"), "branches": base.get("branches") or base.get("outcomes")}
    incoming_contract = {"condition": condition, "branches": normalized_branches}
    previous_provenance = base.get("provenance") if isinstance(base.get("provenance"), dict) else {}
    if (
        previous_provenance.get("status") == "confirmed"
        and not _same(previous_contract, incoming_contract)
        and not resolve_conflict
    ):
        base["provenance"] = {
            "status": "conflicting",
            "evidence_turn_ids": _evidence(previous_provenance.get("evidence_turn_ids"), evidence_turn_id),
            "confidence": 0.0,
            "last_updated_revision": revision,
        }
        return base, True
    base.pop("outcomes", None)
    base["condition"] = condition
    base["branches"] = normalized_branches
    base["provenance"] = {
        "status": "confirmed",
        "evidence_turn_ids": _evidence(previous_provenance.get("evidence_turn_ids"), evidence_turn_id),
        "confidence": 1.0,
        "last_updated_revision": revision,
    }
    return base, False


def merge_work_answers(work_value: Any, submission_value: Any) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        submission = _named(submission_value, "answer_submission")
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("ANSWER_MERGE_INPUT_INVALID", "WorkDefinition 또는 검증된 답변을 해석할 수 없습니다.", trace_id)
    required = ("work_definition_id", "tenant_id", "session_id", "revision", "channel_mode")
    missing = [key for key in required if work.get(key) in (None, "")]
    if missing:
        return _failure("WORK_DEFINITION_SCHEMA_INVALID", "병합할 WorkDefinition 식별자가 없습니다.", trace_id, {"fields": missing})
    if any(str(work.get(key)) != str(submission.get(key)) for key in ("work_definition_id", "tenant_id", "session_id", "channel_mode")):
        return _failure("ANSWER_MERGE_IDENTITY_MISMATCH", "답변과 WorkDefinition의 tenant/session/channel이 다릅니다.", trace_id)
    try:
        current_revision = int(work.get("revision"))
    except (TypeError, ValueError):
        return _failure("ANSWER_REVISION_INVALID", "WorkDefinition revision을 확인할 수 없습니다.", trace_id)

    batch_id = str(submission.get("batch_id") or "")
    idempotency_key = str(submission.get("idempotency_key") or "")
    payload_hash = str(submission.get("payload_sha256") or "")
    if not batch_id or not idempotency_key or not payload_hash:
        return _failure("ANSWER_RECEIPT_INVALID", "batch와 idempotency receipt 정보가 없습니다.", trace_id)
    processed = work.get("processed_answer_batches") if isinstance(work.get("processed_answer_batches"), list) else []
    same_batch = [item for item in processed if isinstance(item, dict) and item.get("batch_id") == batch_id]
    if same_batch:
        receipt = same_batch[-1]
        if receipt.get("idempotency_key") == idempotency_key and receipt.get("payload_sha256") == payload_hash:
            return {
                "ok": True,
                "status": str(work.get("status") or "EXTRACTING"),
                "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": current_revision}],
                "work_definition": work,
                "merge_result": {"idempotent_replay": True, "conflicts": copy.deepcopy(receipt.get("conflicts", [])), "resulting_revision": current_revision},
                "trace_id": trace_id,
            }
        return _failure("ANSWER_BATCH_ALREADY_PROCESSED", "같은 batch가 다른 idempotency key 또는 내용으로 이미 처리되었습니다.", trace_id)
    try:
        expected_revision = int(submission.get("expected_revision"))
    except (TypeError, ValueError):
        return _failure("ANSWER_REVISION_INVALID", "답변 revision을 확인할 수 없습니다.", trace_id)
    if expected_revision != current_revision:
        return _failure("REVISION_CONFLICT", "답변이 최신 WorkDefinition revision을 대상으로 하지 않습니다.", trace_id, {"expected_revision": expected_revision, "current_revision": current_revision})

    answers = submission.get("answers")
    if not isinstance(answers, list) or not answers:
        return _failure("ANSWER_LIST_INVALID", "병합할 답변이 없습니다.", trace_id)
    updated = copy.deepcopy(work)
    new_revision = current_revision + 1
    conflicts: list[dict[str, Any]] = []
    changed_paths: list[str] = []
    for answer in answers[:100]:
        if not isinstance(answer, dict):
            return _failure("ANSWER_ITEM_INVALID", "답변 항목 형식이 올바르지 않습니다.", trace_id)
        paths = answer.get("target_paths") if isinstance(answer.get("target_paths"), list) else []
        if not paths:
            return _failure("ANSWER_TARGET_PATH_MISSING", "답변이 갱신할 target path가 없습니다.", trace_id, {"question_id": answer.get("question_id")})
        for raw_path in paths[:10]:
            path = str(raw_path)
            tokens = _path_tokens(path)
            if not tokens or tokens[0] in {"work_definition_id", "tenant_id", "owner_id", "session_id", "revision", "channel_mode", "approved_hash", "preview_hash", "source_requests"}:
                return _failure("ANSWER_TARGET_PATH_FORBIDDEN", "답변이 변경할 수 없는 경로입니다.", trace_id, {"path": path})
            current = _get_path(updated, tokens)
            if len(tokens) == 1 and str(tokens[0]) in LIST_FIELDS:
                incoming_list = _confirmed_list(answer.get("value"), path=path, revision=new_revision, evidence_turn_id=str(answer.get("evidence_turn_id") or ""))
                existing_confirmed = isinstance(current, list) and current and all(isinstance(item, dict) and ((item.get("provenance") or {}).get("status") == "confirmed") for item in current)
                if existing_confirmed and not _same(current, incoming_list) and not bool(answer.get("resolve_conflict")):
                    conflicts.append({"path": path, "question_id": answer.get("question_id"), "reason": "CONFIRMED_VALUE_CHANGED"})
                    unresolved = updated.get("unresolved") if isinstance(updated.get("unresolved"), list) else []
                    conflict_material = f"{batch_id}|{path}"
                    unresolved.append({"id": f"conflict-{hashlib.sha256(conflict_material.encode('utf-8')).hexdigest()[:16]}", "path": path, "existing_value": copy.deepcopy(current), "incoming_value": incoming_list, "provenance": {"status": "conflicting", "evidence_turn_ids": [str(answer.get("evidence_turn_id") or "")], "confidence": 0.0, "last_updated_revision": new_revision}})
                    updated["unresolved"] = unresolved
                    continue
                merged_value = incoming_list
                conflict = False
            elif len(tokens) == 2 and tokens[0] == "decisions" and isinstance(tokens[1], int):
                try:
                    merged_value, conflict = _merge_decision(
                        current,
                        answer.get("value"),
                        revision=new_revision,
                        evidence_turn_id=str(answer.get("evidence_turn_id") or ""),
                        resolve_conflict=bool(answer.get("resolve_conflict")),
                    )
                except ValueError as exc:
                    return _failure(
                        "ANSWER_DECISION_INVALID",
                        "분기 답변은 condition과 두 개 이상의 branches를 가진 JSON object여야 합니다.",
                        trace_id,
                        {"path": path, "reason": str(exc)},
                    )
            else:
                merged_value, conflict = _merge_fact(current, answer.get("value"), revision=new_revision, evidence_turn_id=str(answer.get("evidence_turn_id") or ""), resolve_conflict=bool(answer.get("resolve_conflict")))
            if not _set_path(updated, tokens, merged_value):
                return _failure("ANSWER_TARGET_PATH_INVALID", "답변 target path를 WorkDefinition에 적용할 수 없습니다.", trace_id, {"path": path})
            changed_paths.append(path)
            if conflict:
                conflicts.append({"path": path, "question_id": answer.get("question_id"), "reason": "CONFIRMED_VALUE_CHANGED"})

    updated["revision"] = new_revision
    updated["approved_hash"] = None
    updated["status"] = "NEEDS_CLARIFICATION" if conflicts else "EXTRACTING"
    receipt = {
        "batch_id": batch_id,
        "submission_id": submission.get("submission_id"),
        "idempotency_key": idempotency_key,
        "payload_sha256": payload_hash,
        "resulting_revision": new_revision,
        "changed_paths": sorted(set(changed_paths)),
        "conflicts": copy.deepcopy(conflicts),
    }
    processed.append(receipt)
    updated["processed_answer_batches"] = processed[-100:]
    return {
        "ok": True,
        "status": updated["status"],
        "artifact_refs": [{"kind": "work_definition", "id": updated["work_definition_id"], "revision": new_revision}],
        "work_definition": updated,
        "merge_result": {"idempotent_replay": False, "conflicts": conflicts, "changed_paths": sorted(set(changed_paths)), "resulting_revision": new_revision},
        "trace_id": trace_id,
    }


class WorkAnswerMergerComponent(Component):
    display_name = "15 업무 답변 병합"
    description = "검증된 답변을 provenance와 confirmed 충돌을 보존하며 한 revision으로 idempotent 병합합니다."
    icon = "GitMerge"
    name = "WorkAnswerMerger"

    inputs = [
        DataInput(name="work_definition", display_name="WorkDefinition", input_types=["Data", "JSON"], required=True),
        DataInput(name="answer_submission", display_name="검증된 답변", input_types=["Data", "JSON"], required=True),
    ]
    outputs = [Output(name="merged_work_definition", display_name="병합 WorkDefinition", method="build_merged_definition", types=["Data"])]

    def build_merged_definition(self) -> Data:
        result = merge_work_answers(getattr(self, "work_definition", None), getattr(self, "answer_submission", None))
        self.status = {"ok": result["ok"], "status": result["status"], "revision": (result.get("work_definition") or {}).get("revision")}
        return Data(data=result)

